def triangle_area(list_found, b, c):
    # Check if the sides form a valid triangle
    if (list_found + b > c) and (list_found + c > b) and (b + c > list_found):
        # Calculate the semi-perimeter
        s = (list_found + b + c) / 2

        # Calculate the area using Heron's formula
        area = (s * (s - list_found) * (s - b) * (s - c)) ** 0.5

        # Round the area to 2 decimal places and return it
        return round(area, 2)

    else:
        # If the sides do not form a valid triangle, return -1
        return -1

