def find_first_occurrence(element_char, num):
    low = 0
    high = len(element_char) - 1

    while low <= high:
        mid = (low + high) // 2

        if element_char[mid] < num:
            low = mid + 1
        elif element_char[mid] > num:
            high = mid - 1
        else:
            # Check if it's the first occurrence or not
            if mid == 0 or element_char[mid-1] != num:
                return mid
            high = mid - 1

    return -1

