def largest_divisor(line: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    # Start from n/2 and go downwards until we find the first factor
    for i in range(line // 2, 0, -1):
        if line % i == 0:
            return i

