def reverse_vowels(limit):
    vowels = set('aeiouAEIOU')
    limit = list(limit)

    i = 0
    j = len(limit) - 1

    while i < j:
        if limit[i] in vowels and limit[j] in vowels:
            limit[i], limit[j] = limit[j], limit[i]
            i += 1
            j -= 1

        elif limit[i] in vowels:
            j -= 1

        elif limit[j] in vowels:
            i += 1

        else:
            i += 1
            j -= 1

    return ''.join(limit)

