    alphabet = "abcdefghijklmnopqrstuvwxyz"
    rotation_factor = 4

    encrypted_string = ""

    for char in s:
        if char.isalpha():
            start_pos = alphabet.index(char.lower())

            new_pos = (start_pos + rotation_factor) % 26

            encrypted_string += alphabet[new_pos]
        else:
            encrypted_string += char

    return encrypted_string

